package com.lumora.sms.security.reset;
import com.lumora.sms.entity.*; import com.lumora.sms.exception.BusinessRuleViolationException; import com.lumora.sms.repository.*; import com.lumora.sms.security.audit.SecurityAuditService; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
/** Issues and consumes short-lived, hashed, single-use password reset credentials. */
@Service @RequiredArgsConstructor public class PasswordResetService { private final UserRepository users; private final PasswordResetTokenRepository tokens; private final PasswordEncoder encoder; private final PasswordResetMailService mail; private final SecurityAuditService audit; @Value("${app.security.reset.expiry-minutes:30}") private long expiryMinutes;
 @Transactional public void request(String email){users.findByEmail(email).ifPresent(user->{tokens.findByUserIdAndUsedAtIsNull(user.getId()).forEach(t->{t.setUsedAt(LocalDateTime.now());});String raw=generateToken();PasswordResetToken token=new PasswordResetToken();token.setUser(user);token.setTokenHash(hash(raw));token.setExpiresAt(LocalDateTime.now().plusMinutes(expiryMinutes));tokens.save(token);mail.send(user,raw);audit.record(user.getUsername(),"PASSWORD_RESET_REQUESTED",null);});}
 @Transactional public void reset(ResetPasswordRequest request){PasswordResetToken token=tokens.findByTokenHashAndUsedAtIsNull(hash(request.token())).orElseThrow(()->new BusinessRuleViolationException("The reset token is invalid or has already been used."));if(!token.getExpiresAt().isAfter(LocalDateTime.now()))throw new BusinessRuleViolationException("The reset token has expired.");User user=token.getUser();user.setPasswordHash(encoder.encode(request.newPassword()));user.setPasswordChangedAt(LocalDateTime.now());user.setFailedLoginAttempts(0);user.setLockoutUntil(null);token.setUsedAt(LocalDateTime.now());audit.record(user.getUsername(),"PASSWORD_CHANGED",null);}
 private String generateToken(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);} private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException("SHA-256 is unavailable",e);}}
}
